package main

import (
	"fmt"
	"runtime"
	"time"
)

type box struct{ n int }

func main() {
	ch := make(chan int, 3)
	for i := 0; i < 3; i++ {
		b := &box{i}
		runtime.AddCleanup(b, func(n int) { ch <- n }, i)
	}
	seen := 0
	for i := 0; i < 200 && seen < 3; i++ {
		runtime.GC()
		time.Sleep(time.Millisecond)
		for {
			select {
			case <-ch:
				seen++
				continue
			default:
			}
			break
		}
	}
	fmt.Println("cleanups:", seen)

	keep := &box{99}
	h := runtime.AddCleanup(keep, func(int) { fmt.Println("must not run") }, 0)
	h.Stop()
	runtime.GC()
	runtime.KeepAlive(keep)
	fmt.Println("stopped cleanup did not run")
}

